[CmdletBinding()]
param([Parameter(Position=0)][string]$FilePath)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
$script:State=[ordered]@{XmlPath='';Backglass=$null;Dmd=$null;GrillHeight=0;CalculatedRes=$null}
function Dispose-Image([System.Drawing.Image]$Image){if($null-ne$Image){$Image.Dispose()}}
function Clear-Images{Dispose-Image $script:State.Backglass;Dispose-Image $script:State.Dmd;$script:State.Backglass=$null;$script:State.Dmd=$null}
function Get-NodeText([System.Xml.XmlNode]$Node){if($null-eq$Node){return $null};foreach($n in 'Image','Content','Value','InnerText'){$p=$Node.PSObject.Properties[$n];if($null-ne$p -and -not [string]::IsNullOrWhiteSpace([string]$p.Value)){return ([string]$p.Value).Trim()}};return $null}
function Get-Base64([System.Xml.XmlNodeList]$Nodes){foreach($node in $Nodes){$text=Get-NodeText $node;if([string]::IsNullOrWhiteSpace($text)){continue};try{[Convert]::FromBase64String(($text-replace '\s+',''))|Out-Null;return $text}catch [FormatException]{}};return $null}
function Convert-ToBitmap([string]$Text){if([string]::IsNullOrWhiteSpace($Text)){return $null};$stream=[IO.MemoryStream]::new([Convert]::FromBase64String(($Text-replace '\s+','')));$image=$null;try{$image=[Drawing.Image]::FromStream($stream);return [Drawing.Bitmap]::new($image)}finally{if($null-ne$image){$image.Dispose()};$stream.Dispose()}}
function Get-GrillHeight([xml]$Xml){foreach($node in $Xml.SelectNodes('//*[local-name()="GrillHeight"]')){$m=[regex]::Match((Get-NodeText $node),'\d+');if($m.Success){$height=0;if([int]::TryParse($m.Value,[ref]$height)-and$height-gt 0){return$height}}};return 0}
function Get-Layout{param([int]$MonitorWidth,[int]$MonitorHeight,[Drawing.Image]$Backglass,[Drawing.Image]$Dmd,[int]$GrillHeight,[bool]$CropGrill,[int]$DmdWidth,[int]$Gap,[int]$Offset,[string]$OffsetMode,[string]$Order,[bool]$GrillSelected)
$sourceWidth=$Backglass.Width;$sourceHeight=$Backglass.Height;$cropped=$CropGrill-and-not$GrillSelected-and$GrillHeight-gt 0;if($cropped){if($GrillHeight-ge$sourceHeight){throw "XML grill height is not smaller than the backglass height."};$sourceHeight-=$GrillHeight};$backglassWidth=$MonitorWidth;$backglassHeight=[math]::Max(1,[int][math]::Round($backglassWidth*$sourceHeight/$sourceWidth));$dmdHeight=if($null-ne$Dmd){[math]::Max(1,[int][math]::Round($DmdWidth*$Dmd.Height/$Dmd.Width))}else{0};$backglassX=0;$secondaryX=[int][math]::Round(($MonitorWidth-$DmdWidth)/2);$backglassY=if($OffsetMode-eq'Top Offset'){$Offset}else{$MonitorHeight-$Offset-$backglassHeight};if($GrillSelected){$secondaryY=$backglassY+$backglassHeight}else{$stackHeight=$backglassHeight+$Gap+$dmdHeight;$stackTop=if($OffsetMode-eq'Top Offset'){$Offset}else{$MonitorHeight-$Offset-$stackHeight};if($Order-eq'Backglass Top / FullDMD Bottom'){$backglassY=$stackTop;$secondaryY=$backglassY+$backglassHeight+$Gap}else{$secondaryY=$stackTop;$backglassY=$secondaryY+$dmdHeight+$Gap}};$warnings=[Collections.Generic.List[string]]::new();if($backglassY-lt 0-or$backglassY+$backglassHeight-gt$MonitorHeight){[void]$warnings.Add('Backglass extends outside the selected monitor.')};if(-not$GrillSelected-and($secondaryX-lt 0-or$secondaryX+$DmdWidth-gt$MonitorWidth)){[void]$warnings.Add('FullDMD extends outside the selected monitor horizontally.')};if(-not$GrillSelected-and($secondaryY-lt 0-or$secondaryY+$dmdHeight-gt$MonitorHeight){[void]$warnings.Add('FullDMD extends outside the selected monitor vertically.')};[pscustomobject]@{MonitorWidth=$MonitorWidth;MonitorHeight=$MonitorHeight;SourceWidth=$sourceWidth;SourceHeight=$sourceHeight;GrillCropped=$cropped;SecondaryIsGrill=$GrillSelected;BackglassX=$backglassX;BackglassY=$backglassY;BackglassWidth=$backglassWidth;BackglassHeight=$backglassHeight;SecondaryX=$secondaryX;SecondaryY=$secondaryY;SecondaryWidth=$DmdWidth;SecondaryHeight=$dmdHeight;Warnings=@($warnings)}}
function Get-ResContent([pscustomobject]$Layout){$dmdWidth=0;$dmdHeight=0;$dmdX=0;$dmdY=0;if(-not$Layout.SecondaryIsGrill){$dmdWidth=$Layout.SecondaryWidth;$dmdHeight=$Layout.SecondaryHeight;$dmdX=$Layout.SecondaryX;$dmdY=$Layout.SecondaryY-$Layout.BackglassY};@('# ScreenRes.txt/.res file','# Playfield width','3840','# Playfield height','2160','# Backglass width',"$($Layout.BackglassWidth)",'# Backglass height',"$($Layout.BackglassHeight)",'# Backglass display device','1','# Backglass X position',"$($Layout.BackglassX)",'# Backglass Y position',"$($Layout.BackglassY)",'# FullDMD width (0 when Grill is selected)',"$dmdWidth",'# FullDMD height (0 when Grill is selected)',"$dmdHeight",'# FullDMD X position',"$dmdX",'# FullDMD Y position relative to backglass',"$dmdY",'# Y-flip (0 = no)','0','# Background X position','0','# Background Y position','0','# Background width','0','# Background height','0','# Background image','black')-join[Environment]::NewLine}
$form=[Windows.Forms.Form]::new();$form.Text='DirectB2S .res Layout Generator & Preview';$form.ClientSize=[Drawing.Size]::new(920,820);$form.StartPosition='CenterScreen';$form.FormBorderStyle='FixedSingle';$form.MaximizeBox=$false;$panel=[Windows.Forms.Panel]::new();$panel.Size=[Drawing.Size]::new(380,780);$panel.Location=[Drawing.Point]::new(10,10);[void]$form.Controls.Add($panel)
function Add-Label([string]$Text,[int]$Top,[bool]$Bold=$false){$label=[Windows.Forms.Label]::new();$label.Text=$Text;$label.Location=[Drawing.Point]::new(10,$Top);$label.AutoSize=$true;if($Bold){$label.Font=[Drawing.Font]::new($label.Font,[Drawing.FontStyle]::Bold)};[void]$panel.Controls.Add($label);return$label}
function Add-Number([int]$Top,[int]$Minimum=0,[int]$Maximum=7680,[int]$Value=0){$number=[Windows.Forms.NumericUpDown]::new();$number.Minimum=$Minimum;$number.Maximum=$Maximum;$number.Value=$Value;$number.Location=[Drawing.Point]::new(150,$Top-3);$number.Size=[Drawing.Size]::new(100,23);[void]$panel.Controls.Add($number);return$number}
function Add-Combo([object[]]$Items,[int]$Top){$combo=[Windows.Forms.ComboBox]::new();[void]$combo.Items.AddRange($Items);$combo.SelectedIndex=0;$combo.DropDownStyle='DropDownList';$combo.Location=[Drawing.Point]::new(150,$Top-3);$combo.Size=[Drawing.Size]::new(210,23);[void]$panel.Controls.Add($combo);return$combo}
$y=10;[void](Add-Label 'Select .directb2s File:' $y);$y+=22;$txtFile=[Windows.Forms.TextBox]::new();$txtFile.Location=[Drawing.Point]::new(10,$y);$txtFile.Size=[Drawing.Size]::new(270,23);$txtFile.ReadOnly=$true;[void]$panel.Controls.Add($txtFile);$btnBrowse=[Windows.Forms.Button]::new();$btnBrowse.Text='Browse...';$btnBrowse.Location=[Drawing.Point]::new(285,$y-1);$btnBrowse.Size=[Drawing.Size]::new(75,25);[void]$panel.Controls.Add($btnBrowse);$y+=50;[void](Add-Label 'Backglass Monitor Resolution (W x H):' $y $true);$y+=25;$numMonW=Add-Number $y 500 7680 1440;$lblX=Add-Label 'x' ($y+3);$lblX.Location=[Drawing.Point]::new(118,$y+3);$numMonH=Add-Number $y 500 7680 2560;$numMonH.Location=[Drawing.Point]::new(135,$y);$y+=35;$lblGrillInfo=Add-Label 'XML Grill Height: 0 px' $y $true;$y+=25;$chkCutGrill=[Windows.Forms.CheckBox]::new();$chkCutGrill.Text='Crop embedded grill from backglass (FullDMD only)';$chkCutGrill.Location=[Drawing.Point]::new(10,$y);$chkCutGrill.AutoSize=$true;$chkCutGrill.Enabled=$false;[void]$panel.Controls.Add($chkCutGrill);$y+=35;[void](Add-Label 'Visible Secondary Screen:' $y $true);$cmbType=Add-Combo @('Grill','FullDMD') $y;$y+=30;[void](Add-Label 'Offset Mode:' $y);$cmbOffsetMode=Add-Combo @('Top Offset','Bottom Offset') $y;$y+=30;[void](Add-Label 'Offset (px):' $y);$numOffset=Add-Number $y;$y+=30;[void](Add-Label 'Vertical Stacking Order:' $y);$cmbOrder=Add-Combo @('Backglass Top / FullDMD Bottom','FullDMD Top / Backglass Bottom') $y;$y+=30;[void](Add-Label 'FullDMD Width (px):' $y);$numDmdW=Add-Number $y 100 3840 1080;$y+=30;[void](Add-Label 'Element Gap (px):' $y);$numGap=Add-Number $y 0 500 20;$y+=40;$btnSave=[Windows.Forms.Button]::new();$btnSave.Text='Generate .res File';$btnSave.Size=[Drawing.Size]::new(350,40);$btnSave.Location=[Drawing.Point]::new(10,$y);$btnSave.BackColor=[Drawing.Color]::LightGreen;$btnSave.Enabled=$false;[void]$panel.Controls.Add($btnSave);$y+=50;$txtStatus=[Windows.Forms.TextBox]::new();$txtStatus.Multiline=$true;$txtStatus.ReadOnly=$true;$txtStatus.ScrollBars='Vertical';$txtStatus.Size=[Drawing.Size]::new(350,200);$txtStatus.Location=[Drawing.Point]::new(10,$y);[void]$panel.Controls.Add($txtStatus);$picPreview=[Windows.Forms.PictureBox]::new();$picPreview.Size=[Drawing.Size]::new(480,780);$picPreview.Location=[Drawing.Point]::new(400,10);$picPreview.BackColor=[Drawing.Color]::FromArgb(30,30,30);$picPreview.BorderStyle='FixedSingle';[void]$form.Controls.Add($picPreview)
function Update-Preview{if($null-eq$script:State.Backglass){return};$grillSelected=([string]$cmbType.SelectedItem-eq'Grill');try{$layout=Get-Layout ([int]$numMonW.Value) ([int]$numMonH.Value) $script:State.Backglass $script:State.Dmd $script:State.GrillHeight $chkCutGrill.Checked ([int]$numDmdW.Value) ([int]$numGap.Value) ([int]$numOffset.Value) ([string]$cmbOffsetMode.SelectedItem) ([string]$cmbOrder.SelectedItem) $grillSelected}catch{$txtStatus.Text="Layout error:`r`n$($_.Exception.Message)";return};$script:State.CalculatedRes=$layout;$txtStatus.Text="VISIBLE SECONDARY: $($cmbType.SelectedItem)`r`nOFFSET: $($cmbOffsetMode.SelectedItem), $($numOffset.Value) px`r`n`r`nBackglass: $($layout.BackglassWidth)x$($layout.BackglassHeight) at ($($layout.BackglassX),$($layout.BackglassY))`r`nFullDMD: $($layout.SecondaryWidth)x$($layout.SecondaryHeight) at ($($layout.SecondaryX),$($layout.SecondaryY))`r`n`r`nGrill is embedded in BackglassImage and has no separate .res position.`r`n$($layout.Warnings -join "`r`n")";$bitmap=[Drawing.Bitmap]::new($picPreview.ClientSize.Width,$picPreview.ClientSize.Height);$graphics=[Drawing.Graphics]::FromImage($bitmap);try{$graphics.Clear([Drawing.Color]::FromArgb(30,30,30));$scale=[math]::Min(($picPreview.ClientSize.Width-40)/$layout.MonitorWidth,($picPreview.ClientSize.Height-40)/$layout.MonitorHeight);$ox=[int](($picPreview.ClientSize.Width-$layout.MonitorWidth*$scale)/2);$oy=[int](($picPreview.ClientSize.Height-$layout.MonitorHeight*$scale)/2);$graphics.FillRectangle([Drawing.Brushes]::Black,$ox,$oy,[int]($layout.MonitorWidth*$scale),[int]($layout.MonitorHeight*$scale));$bg=[Drawing.Rectangle]::new($ox+[int]($layout.BackglassX*$scale),$oy+[int]($layout.BackglassY*$scale),[int]($layout.BackglassWidth*$scale),[int]($layout.BackglassHeight*$scale));$src=[Drawing.Rectangle]::new(0,0,$layout.SourceWidth,$layout.SourceHeight);$graphics.DrawImage($script:State.Backglass,$bg,$src,[Drawing.GraphicsUnit]::Pixel);$graphics.DrawRectangle([Drawing.Pens]::Yellow,$bg);if(-not$grillSelected){$secondary=[Drawing.Rectangle]::new($ox+[int]($layout.SecondaryX*$scale),$oy+[int]($layout.SecondaryY*$scale),[int]($layout.SecondaryWidth*$scale),[int]($layout.SecondaryHeight*$scale));if($null-ne$script:State.Dmd){$graphics.DrawImage($script:State.Dmd,$secondary)}else{$graphics.FillRectangle([Drawing.Brushes]::DarkGray,$secondary);$graphics.DrawString('No FullDMD Found',[Drawing.SystemFonts]::DefaultFont,[Drawing.Brushes]::White,$secondary.X+5,$secondary.Y+5)};$graphics.DrawRectangle([Drawing.Pens]::OrangeRed,$secondary)}}finally{$graphics.Dispose()};$old=$picPreview.Image;$picPreview.Image=$bitmap;Dispose-Image $old}
function Load-DirectB2S([string]$Path){try{$xml=[xml](Get-Content -LiteralPath $Path -Raw);Clear-Images;$script:State.XmlPath=$Path;$txtFile.Text=[IO.Path]::GetFileName($Path);$script:State.GrillHeight=Get-GrillHeight $xml;$script:State.Backglass=Convert-ToBitmap (Get-Base64 $xml.SelectNodes('//*[local-name()="BackglassImage"]'));if($null-eq$script:State.Backglass){throw 'Could not locate valid BackglassImage data.'};$script:State.Dmd=Convert-ToBitmap (Get-Base64 $xml.SelectNodes('//*[local-name()="DMDImage"]'));$lblGrillInfo.Text="XML Grill Height: $($script:State.GrillHeight) px";$chkCutGrill.Checked=($script:State.GrillHeight-gt 0);$chkCutGrill.Enabled=$true;$btnSave.Enabled=$true;Update-Preview}catch{Clear-Images;$btnSave.Enabled=$false;$txtStatus.Text="Error reading .directb2s file:`r`n$($_.Exception.Message)"}}
$btnBrowse.Add_Click({$dialog=[Windows.Forms.OpenFileDialog]::new();$dialog.Filter='DirectB2S Files (*.directb2s)|*.directb2s|All files (*.*)|*.*';try{if($dialog.ShowDialog()-eq'OK'){Load-DirectB2S $dialog.FileName}}finally{$dialog.Dispose()}});$btnSave.Add_Click({$resPath=[IO.Path]::ChangeExtension($script:State.XmlPath,'.res');Set-Content -LiteralPath $resPath -Value (Get-ResContent $script:State.CalculatedRes) -Encoding ASCII;[Windows.Forms.MessageBox]::Show(".res generated at:`r`n$resPath")|Out-Null});foreach($control in @($numMonW,$numMonH,$numDmdW,$numOffset,$numGap)){$control.Add_ValueChanged({Update-Preview})};foreach($control in @($cmbType,$cmbOffsetMode,$cmbOrder)){$control.Add_SelectedIndexChanged({Update-Preview})};$chkCutGrill.Add_CheckedChanged({Update-Preview});$form.Add_FormClosed({Clear-Images;Dispose-Image $picPreview.Image});if(-not[string]::IsNullOrWhiteSpace($FilePath)){$form.Add_Shown({Load-DirectB2S $FilePath})};[void]$form.ShowDialog()